import type { Page, Locator } from '@playwright/test';

/**
 * Page Object for the InvenTree Login Page.
 * Implements navigation, credentials entry, form submission, and login verification.
 */
export class LoginPage {
  readonly page: Page;
  readonly usernameInput: Locator;
  readonly passwordInput: Locator;
  readonly loginButton: Locator;
  readonly errorMessage: Locator;

  constructor(page: Page) {
    this.page = page;
    this.usernameInput = page
      .getByPlaceholder(/username/i)
      .or(page.getByLabel(/username/i))
      .first();
    this.passwordInput = page
      .getByPlaceholder(/password/i)
      .or(page.getByLabel(/password/i))
      .first();
    this.loginButton = page.getByRole('button', { name: /log in|sign in/i });
    this.errorMessage = page
      .getByRole('alert')
      .or(page.getByText(/unable to log in|invalid credentials|authentication error/i));
  }

  /** Navigates to the login page */
  async navigate(): Promise<void> {
    await this.page.goto('/web/login');
    await this.page.waitForLoadState('domcontentloaded');
  }

  /** Fills user credentials into the form */
  async fillCredentials(username: string, password: string): Promise<void> {
    await this.usernameInput.fill(username);
    await this.passwordInput.fill(password);
  }

  /** Submits the login form */
  async submit(): Promise<void> {
    await this.loginButton.click();
  }

  /** Checks if user is authenticated and redirected away from login */
  async isLoggedIn(): Promise<boolean> {
    try {
      await this.page.waitForURL((url) => !url.pathname.includes('/login'), {
        timeout: 10_000,
      });
      return true;
    } catch {
      return false;
    }
  }

  /** Returns error message text when login fails */
  async getErrorMessage(): Promise<string> {
    await this.errorMessage.first().waitFor({ state: 'visible', timeout: 5_000 });
    return (await this.errorMessage.first().textContent()) ?? '';
  }
}

import type { Page, Locator } from '@playwright/test';

/**
 * Page Object for InvenTree Parts List View.
 * Handles table search, part row retrieval, pagination, and opening part creation.
 */
export class PartsListPage {
  readonly page: Page;
  readonly searchInput: Locator;
  readonly createPartButton: Locator;
  readonly tableRows: Locator;
  readonly paginationNav: Locator;

  constructor(page: Page) {
    this.page = page;
    this.searchInput = page
      .getByPlaceholder(/search/i)
      .or(page.getByLabel(/search/i))
      .first();
    this.createPartButton = page
      .getByRole('button', { name: /new part|create part|\+ part|add part/i })
      .or(page.getByTestId('create-part-button'))
      .first();
    this.tableRows = page.getByRole('row');
    this.paginationNav = page
      .getByRole('navigation', { name: /pagination/i })
      .or(page.getByRole('button', { name: /next page|previous page/i }))
      .first();
  }

  /** Navigates directly to the Parts list page */
  async navigate(): Promise<void> {
    await this.page.goto('/web/part/');
    await this.page.waitForLoadState('domcontentloaded');
  }

  /** Clicks button to open Create Part dialog or form */
  async clickCreatePart(): Promise<void> {
    await this.createPartButton.click();
  }

  /** Searches for parts by keyword */
  async searchPart(keyword: string): Promise<void> {
    await this.searchInput.fill(keyword);
    await this.page.keyboard.press('Enter');
    await this.page.waitForLoadState('networkidle');
  }

  /** Locates a row in the table matching part name */
  getPartRow(name: string): Locator {
    return this.page.getByRole('row', { name: new RegExp(name, 'i') });
  }

  /** Counts number of rows visible in the parts table */
  async getPartCount(): Promise<number> {
    await this.page.waitForLoadState('domcontentloaded');
    const rows = await this.tableRows.count();
    return Math.max(0, rows - 1);
  }
}

import type { Page, Locator } from '@playwright/test';

/**
 * Page Object for InvenTree Part Detail View.
 * Provides access to part title, action buttons, field values, and deletion confirmation.
 */
export class PartDetailPage {
  readonly page: Page;
  readonly titleHeading: Locator;
  readonly editButton: Locator;
  readonly deleteButton: Locator;
  readonly confirmDeleteButton: Locator;
  readonly cancelDeleteButton: Locator;

  constructor(page: Page) {
    this.page = page;
    this.titleHeading = page.getByRole('heading', { level: 1 }).first();
    this.editButton = page
      .getByRole('button', { name: /edit part|edit/i })
      .or(page.getByTestId('edit-part-button'))
      .first();
    this.deleteButton = page
      .getByRole('button', { name: /delete part|delete/i })
      .or(page.getByTestId('delete-part-button'))
      .first();
    this.confirmDeleteButton = page
      .getByRole('dialog')
      .getByRole('button', { name: /confirm|delete|yes/i });
    this.cancelDeleteButton = page
      .getByRole('dialog')
      .getByRole('button', { name: /cancel|no/i });
  }

  /** Navigates directly to a part detail page by ID */
  async navigate(partId: number | string): Promise<void> {
    await this.page.goto(`/web/part/${partId}/`);
    await this.page.waitForLoadState('domcontentloaded');
  }

  /** Returns primary title/heading of the part */
  async getTitle(): Promise<string> {
    await this.titleHeading.waitFor({ state: 'visible', timeout: 10_000 });
    return (await this.titleHeading.textContent()) ?? '';
  }

  /** Clicks the Edit Part action button */
  async clickEdit(): Promise<void> {
    await this.editButton.click();
  }

  /** Clicks the Delete Part action button to trigger confirmation modal */
  async clickDelete(): Promise<void> {
    await this.deleteButton.click();
  }

  /** Confirms deletion in the confirmation modal dialog */
  async confirmDelete(): Promise<void> {
    await this.confirmDeleteButton.click();
  }

  /** Cancels deletion dialog */
  async cancelDelete(): Promise<void> {
    await this.cancelDeleteButton.click();
  }

  /** Retrieves text value of a labeled field or detail row */
  async getFieldValue(fieldName: string): Promise<string> {
    const fieldLocator = this.page
      .getByText(new RegExp(fieldName, 'i'))
      .locator('..')
      .locator('dd, span, div')
      .first();
    return (await fieldLocator.textContent()) ?? '';
  }
}

import type { Page, Locator } from '@playwright/test';

/**
 * Page Object for Create and Edit Part modal or form view.
 * Handles field input, category selection, boolean toggles, validation, and submission.
 */
export class PartFormPage {
  readonly page: Page;
  readonly nameInput: Locator;
  readonly descriptionInput: Locator;
  readonly ipnInput: Locator;
  readonly categoryInput: Locator;
  readonly activeCheckbox: Locator;
  readonly submitButton: Locator;
  readonly cancelButton: Locator;

  constructor(page: Page) {
    this.page = page;
    this.nameInput = page
      .getByLabel(/^name/i)
      .or(page.getByPlaceholder(/part name/i))
      .first();
    this.descriptionInput = page.getByLabel(/description/i).first();
    this.ipnInput = page.getByLabel(/ipn|part number/i).first();
    this.categoryInput = page
      .getByLabel(/category/i)
      .or(page.getByPlaceholder(/select category/i))
      .first();
    this.activeCheckbox = page
      .getByLabel(/active/i)
      .or(page.getByRole('checkbox', { name: /active/i }))
      .first();
    this.submitButton = page
      .getByRole('button', { name: /submit|save|create|confirm/i })
      .first();
    this.cancelButton = page
      .getByRole('button', { name: /cancel/i })
      .first();
  }

  /** Fills the required Part Name field */
  async fillName(name: string): Promise<void> {
    await this.nameInput.fill(name);
  }

  /** Fills the optional Part Description field */
  async fillDescription(description: string): Promise<void> {
    await this.descriptionInput.fill(description);
  }

  /** Fills the Internal Part Number (IPN) */
  async fillIPN(ipn: string): Promise<void> {
    await this.ipnInput.fill(ipn);
  }

  /** Selects a category from category picker or dropdown */
  async selectCategory(categoryName: string): Promise<void> {
    await this.categoryInput.click();
    await this.page
      .getByRole('option', { name: new RegExp(categoryName, 'i') })
      .or(this.page.getByText(categoryName, { exact: true }))
      .first()
      .click();
  }

  /** Toggles the active status flag */
  async toggleActive(active: boolean): Promise<void> {
    const isChecked = await this.activeCheckbox.isChecked();
    if (isChecked !== active) {
      await this.activeCheckbox.click();
    }
  }

  /** Submits the Part form */
  async submit(): Promise<void> {
    await this.submitButton.click();
  }

  /** Cancels the Part form */
  async cancel(): Promise<void> {
    await this.cancelButton.click();
  }

  /** Retrieves validation error message associated with a field */
  async getValidationError(fieldName: string): Promise<string> {
    const errorLocator = this.page
      .getByText(new RegExp(`${fieldName}.*required|invalid|must|cannot`, 'i'))
      .or(this.page.getByRole('alert'))
      .first();
    await errorLocator.waitFor({ state: 'visible', timeout: 5_000 });
    return (await errorLocator.textContent()) ?? '';
  }
}

import type { Page, Locator } from '@playwright/test';

/**
 * Page Object for Part Category tree, creation modal, and detail views.
 */
export class CategoryPage {
  readonly page: Page;
  readonly createCategoryButton: Locator;
  readonly nameInput: Locator;
  readonly descriptionInput: Locator;
  readonly parentInput: Locator;
  readonly submitButton: Locator;
  readonly cancelButton: Locator;
  readonly editCategoryButton: Locator;
  readonly deleteCategoryButton: Locator;
  readonly confirmDeleteButton: Locator;

  constructor(page: Page) {
    this.page = page;
    this.createCategoryButton = page
      .getByRole('button', { name: /new category|add category|\+ category/i })
      .first();
    this.nameInput = page.getByLabel(/^name/i).first();
    this.descriptionInput = page.getByLabel(/description/i).first();
    this.parentInput = page.getByLabel(/parent/i).first();
    this.submitButton = page
      .getByRole('button', { name: /save|submit|create/i })
      .first();
    this.cancelButton = page.getByRole('button', { name: /cancel/i }).first();
    this.editCategoryButton = page
      .getByRole('button', { name: /edit category|edit/i })
      .first();
    this.deleteCategoryButton = page
      .getByRole('button', { name: /delete category|delete/i })
      .first();
    this.confirmDeleteButton = page
      .getByRole('dialog')
      .getByRole('button', { name: /confirm|delete|yes/i });
  }

  /** Navigates to category tree view */
  async navigate(): Promise<void> {
    await this.page.goto('/web/part/category/');
    await this.page.waitForLoadState('domcontentloaded');
  }

  /** Opens Create Category dialog */
  async clickCreateCategory(): Promise<void> {
    await this.createCategoryButton.click();
  }

  /** Fills category name */
  async fillCategoryName(name: string): Promise<void> {
    await this.nameInput.fill(name);
  }

  /** Fills category description */
  async fillCategoryDescription(description: string): Promise<void> {
    await this.descriptionInput.fill(description);
  }

  /** Selects parent category */
  async selectParentCategory(parentName: string): Promise<void> {
    await this.parentInput.click();
    await this.page.getByRole('option', { name: parentName }).first().click();
  }

  /** Submits category form */
  async submitCategory(): Promise<void> {
    await this.submitButton.click();
  }

  /** Cancels category form */
  async cancelCategory(): Promise<void> {
    await this.cancelButton.click();
  }

  /** Locates category tree node by text */
  getCategoryNode(name: string): Locator {
    return this.page.getByText(name, { exact: true });
  }

  /** Clicks edit category */
  async clickEditCategory(): Promise<void> {
    await this.editCategoryButton.click();
  }

  /** Clicks delete category */
  async clickDeleteCategory(): Promise<void> {
    await this.deleteCategoryButton.click();
  }

  /** Confirms category deletion */
  async confirmDeleteCategory(): Promise<void> {
    await this.confirmDeleteButton.click();
  }
}

import { test as base, type Page } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';

/** Custom fixture types added on top of Playwright's base fixtures */
type AuthFixtures = {
  /**
   * A `Page` that is already authenticated as the test user.
   * The login flow runs once per test via the `authenticatedPage` fixture.
   */
  authenticatedPage: Page;
};

/**
 * Extended Playwright `test` object providing the `authenticatedPage` fixture.
 */
export const test = base.extend<AuthFixtures>({
  authenticatedPage: async ({ page }, use) => {
    const username = process.env.INVENTREE_USERNAME ?? '';
    const password = process.env.INVENTREE_PASSWORD ?? '';

    if (!username || !password) {
      throw new Error(
        'INVENTREE_USERNAME and INVENTREE_PASSWORD must be configured in environment.'
      );
    }

    const loginPage = new LoginPage(page);
    await loginPage.navigate();
    await loginPage.fillCredentials(username, password);
    await loginPage.submit();

    await page.waitForURL((url) => !url.pathname.includes('/login'), {
      timeout: 20_000,
    });

    await use(page);
  },
});

export { expect } from '@playwright/test';

import { test, expect } from '../helpers/fixtures';
import { test as baseTest } from '@playwright/test';
import { PartsListPage } from '../pages/PartsListPage';
import { PartFormPage } from '../pages/PartFormPage';

test.describe('Part Create — UI', () => {
  const uniqueName = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;

  test('TC-UI-017: Part Create — Happy Path via Create Part Form @smoke @regression @auth', async ({
    authenticatedPage,
  }) => {
    test.slow();
    const partsListPage = new PartsListPage(authenticatedPage);
    const partFormPage = new PartFormPage(authenticatedPage);
    const partName = uniqueName('Capacitor-100uF');

    await partsListPage.navigate();
    await partsListPage.clickCreatePart();

    await partFormPage.fillName(partName);
    await partFormPage.fillDescription('Ceramic capacitor 100uF SMD');
    await partFormPage.toggleActive(true);
    await partFormPage.submit();

    await expect(authenticatedPage).toHaveURL(/\/part\//);
    await expect(authenticatedPage.getByText(partName).first()).toBeVisible();
  });

  test('TC-UI-018: Part Create — Missing Name Validation @negative @regression', async ({
    authenticatedPage,
  }) => {
    const partsListPage = new PartsListPage(authenticatedPage);
    const partFormPage = new PartFormPage(authenticatedPage);

    await partsListPage.navigate();
    await partsListPage.clickCreatePart();

    await partFormPage.fillDescription('No name provided');
    await partFormPage.submit();

    const errorMsg = await partFormPage.getValidationError('name');
    expect(errorMsg.length).toBeGreaterThan(0);
  });

  test('TC-UI-019: Part Create — Missing Category Validation @negative @regression', async ({
    authenticatedPage,
  }) => {
    const partsListPage = new PartsListPage(authenticatedPage);
    const partFormPage = new PartFormPage(authenticatedPage);

    await partsListPage.navigate();
    await partsListPage.clickCreatePart();
    await partFormPage.fillName(uniqueName('NoCategory'));
    await partFormPage.submit();

    // Verify either submission completes or validation highlights required category
    await expect(authenticatedPage.getByRole('dialog')).toBeVisible();
  });

  test('TC-UI-020: Part Create — Create Part as Inactive @boundary @regression', async ({
    authenticatedPage,
  }) => {
    test.slow();
    const partsListPage = new PartsListPage(authenticatedPage);
    const partFormPage = new PartFormPage(authenticatedPage);
    const partName = uniqueName('Inactive-Part');

    await partsListPage.navigate();
    await partsListPage.clickCreatePart();
    await partFormPage.fillName(partName);
    await partFormPage.toggleActive(false);
    await partFormPage.submit();

    await expect(authenticatedPage).toHaveURL(/\/part\//);
  });

  test('TC-UI-021: Part Create — Category as Prerequisite @regression', async ({
    authenticatedPage,
  }) => {
    const partsListPage = new PartsListPage(authenticatedPage);
    const partFormPage = new PartFormPage(authenticatedPage);

    await partsListPage.navigate();
    await partsListPage.clickCreatePart();
    await expect(partFormPage.categoryInput).toBeVisible();
  });
});

baseTest.describe('Part Create — Unauthenticated Access', () => {
  baseTest(
    'TC-UI-022: Part Create — Unauthenticated Redirect @auth @negative @smoke',
    async ({ page }) => {
      await page.goto('/web/part/');
      await expect(page).toHaveURL(/\/login/);
      await expect(page.getByRole('button', { name: /log in|sign in/i })).toBeVisible();
    }
  );
});

